function icon(name){const map={
 grid:'<rect x="3" y="3" width="7" height="7"/><rect x="14" y="3" width="7" height="5"/><rect x="14" y="12" width="7" height="9"/><rect x="3" y="14" width="7" height="7"/>',
 crown:'<path d="M3 7l5 5 4-8 4 8 5-5-2 14H5z"/><path d="M7 17h10"/>',check:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 9l2 2 4-5"/><path d="M8 15h8"/>',
 calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18"/>',bars:'<path d="M4 20V10M10 20V5M16 20V13M22 20V8"/>',diamond:'<path d="M7 6h10l3 6-8 9-8-9z"/><path d="M8 12h12M10 6l2 15M14 6l-2 15"/>',
 tag:'<path d="M3 12V4h8l10 10-8 8z"/><circle cx="8" cy="8" r="1"/>',box:'<path d="M3 8l9-5 9 5-9 5z"/><path d="M3 8v9l9 5 9-5V8M12 13v9"/>',alert:'<path d="M12 3l10 18H2z"/><path d="M12 9v5M12 18h.01"/>',
 cube:'<path d="M4 7l8-4 8 4-8 4z"/><path d="M4 7v10l8 4 8-4V7M12 11v10"/>',spark:'<path d="M12 2l2.2 6.8L21 11l-6.8 2.2L12 20l-2.2-6.8L3 11l6.8-2.2z"/>',rocket:'<path d="M12 3c4 2 6 6 5 11l-5 5-5-5C6 9 8 5 12 3z"/><circle cx="12" cy="9" r="1"/><path d="M8 16l-3 3M16 16l3 3"/>',
 pulse:'<path d="M3 13h4l2-6 4 12 2-6h6"/>',star:'<path d="M12 3l2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9z"/>',podium:'<path d="M3 20h18M5 20v-6h4v6M10 20V8h4v12M15 20v-9h4v9"/>'};return `<svg viewBox="0 0 24 24" aria-hidden="true">${map[name]||map.grid}</svg>`}
const pc=id=>`style="--pc:${PLATFORMS[id].color}"`;
function platformLegend(){return `<div class="platform-legend">${Object.entries(PLATFORMS).filter(([id])=>id!=='all').map(([id,p])=>`<span class="legend-item" style="--c:${p.color}"><i></i>${p.long}</span>`).join('')}</div>`}
function lineChart(a=[44,52,48,58,61,69,66,74,79,76,84,91],b=[38,42,47,45,53,56,61,64,68,72,75,80]){const pts=arr=>arr.map((v,i)=>`${(i/(arr.length-1)*100).toFixed(1)},${(100-v).toFixed(1)}`).join(' ');return `<div class="chart"><svg viewBox="0 0 100 100" preserveAspectRatio="none"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="var(--route-accent)" stop-opacity=".22"/><stop offset="1" stop-color="var(--route-accent)" stop-opacity="0"/></linearGradient></defs><g class="chart-grid">${[25,50,75].map(y=>`<line x1="0" y1="${y}" x2="100" y2="${y}"/>`).join('')}</g><polygon class="chart-area" points="0,100 ${pts(a)} 100,100"/><polyline class="chart-line" vector-effect="non-scaling-stroke" points="${pts(a)}"/><polyline class="chart-line secondary" vector-effect="non-scaling-stroke" points="${pts(b)}"/></svg></div><div class="chart-labels"><span>01</span><span>04</span><span>07</span><span>10</span><span>13</span><span>16</span><span>18 июня</span></div>`}
function metric(label,value,note,p='72%',extra=''){return `<section class="panel metric reveal ${extra}"><div class="micro">${label}</div><div class="value" style="margin-top:10px">${value}</div><div class="muted" style="font-size:8px;margin-top:5px">${note}</div><div class="bar"><i style="--p:${p}"></i></div></section>`}
function platformMetric(id,label,value,note,p){return `<section class="panel metric platform-metric reveal" style="--pc:${PLATFORMS[id].color}"><div class="micro">${label}</div><div class="value" style="margin-top:10px">${value}</div><div class="muted" style="font-size:8px;margin-top:5px">${note}</div><div class="bar"><i style="--p:${p}"></i></div></section>`}
function panel(title,body,cls='',tag=''){return `<section class="panel ${cls} reveal"><div class="panel-title"><h2>${title}</h2>${tag?`<small>${tag}</small>`:''}</div>${body}</section>`}
function list(rows){return `<div class="list">${rows.map(r=>`<div class="list-row"><div><strong>${r[0]}</strong><span>${r[1]}</span></div><em>${r[2]}</em></div>`).join('')}</div>`}
function table(headers,rows){return `<div class="table-wrap"><table class="table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map((c,i)=>`<td${i===0?' class="platform-cell" style="--pc:'+((c&&c.pc)||'var(--route-accent)')+'"':''}>${typeof c==='object'?`<strong>${c.v}</strong><br><span>${c.s||''}</span>`:c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function hero(title,desc,value,note,center='72%'){return `<section class="panel hero route-glow platform-line span2 reveal"><div class="hero-grid"><div class="hero-copy"><div class="micro">${activePlatform==='all'?'все площадки':PLATFORMS[activePlatform].long}</div><h2>${title}</h2><p>${desc}</p><div class="hero-number"><div class="value lg">${value}</div><small>${note}</small></div></div><div class="hero-orbit"><div class="core">${center}</div></div></div></section>`}

function dashboard(){return `<div class="grid g3">${hero('Сейчас всё важное помещается в один взгляд','Выручка, выполнение плана и риски собраны в спокойной иерархии. Цвет площадки остаётся только в точках сравнения.','18,6 млн ₽','выручка сегодня','92%')}${panel('Фокус дня',list([['Реклама WB','Ставка выросла, но ROMI держится','проверить'],['Ozon: цена','Ниже WB на 3 ключевых SKU','сравнить'],['OOS','2 позиции закончатся < 10 дней','заказать'],['Новинки','3 карточки готовы к запуску','согласовать']]),'panel-pad platform-focus','4 решения')}</div><div class="grid g5 section-gap">${platformMetric('wb','Wildberries','7,9 млн ₽','43% оборота','78%')}${platformMetric('ozon','Ozon','5,4 млн ₽','29% оборота','65%')}${platformMetric('ym','Я.Маркет','2,1 млн ₽','11% оборота','48%')}${platformMetric('goldapple','Золотое Яблоко','1,7 млн ₽','9% оборота','39%')}${platformMetric('letu','Л’Этуаль','1,5 млн ₽','8% оборота','34%')}</div><div class="grid g3 section-gap">${panel('Динамика результата',lineChart(),'panel-pad span2','18 дней')}${panel('Пульс команды',list([['План-факт','92% к плану','в норме'],['Маржа','42,6%','+1,8 п.п.'],['Реклама','ДРР 8,6%','внимание'],['Задачи','23 активные','14 просрочены']]),'panel-pad','сейчас')}</div>`}
function executive(){return `<div class="grid g3">${hero('Управленческий экран отвечает: где нужно решение','Сначала итог, затем доказательство, после — исключения. Полная таблица остаётся во втором слое.','43,8%','маржа портфеля','88%')}${panel('Решения на сегодня',list([['Поднять коридор цены','3 SKU ниже безопасного MIN','до 12:00'],['Перенести рекламу','2 кампании WB без запаса маржи','сегодня'],['Ускорить поставку','Краснодар: риск OOS через 8 дней','срочно'],['Назначить owner','4 задачи без ответственного','сейчас']]),'panel-pad platform-focus','4 сигнала')}</div><div class="grid g4 section-gap">${metric('Оборот','142,4 млн ₽','77,6% плана','78%')}${metric('Маржа','43,8%','план 42,4%','84%')}${metric('Реклама','44,9%','выполнение бюджета','45%')}${metric('Команда','5 / 7','в плане','71%')}</div><div class="grid g2 section-gap">${panel('План → факт → прогноз',lineChart([47,49,53,58,62,66,70,73,77,81,86,92],[52,55,58,61,64,67,70,73,76,79,82,85]),'panel-pad','управленческий тренд')}${panel('Исключения, а не шум',list([['Риск маржи','gel_antiakne_20ml_v2','−312 594 ₽'],['Риск рекламы','retinol_syvorotka_1_30ml','−287 209 ₽'],['Рост','Сыворотка для лица','+1 222 заказа'],['Like for like','Портфель КЗ','+4 952']]),'panel-pad','4 исключения')}</div>`}
function control(){const task=(t,s,owner,p='wb')=>`<div class="task" style="--pc:${PLATFORMS[p].color}"><strong>${t}</strong><small>${s}</small><div class="task-foot"><span class="status">${owner}</span><span class="avatar">${owner.slice(0,2)}</span></div></div>`;return `<div class="grid g4">${metric('Активные','23','в работе','61%')}${metric('Просрочено','14','нужен новый срок','42%','')}${metric('Без owner','4','назначить ответственных','24%')}${metric('Автосигналы','7','портал создал сам','70%')}</div><section class="panel panel-pad section-gap platform-line reveal"><div class="panel-title"><h2>Очередь исполнения</h2><small>команда · сроки · площадки</small></div><div class="kanban"><div class="kanban-col"><div class="kanban-head"><span>Новые</span><span>7</span></div>${task('КЗ WB: реклама режет доходность','Проверить кампании без запаса маржи','Кирилл','wb')}${task('Ozon: разрыв цены','Сверить ведущие позиции','Мария','ozon')}</div><div class="kanban-col"><div class="kanban-head"><span>В работе</span><span>9</span></div>${task('Подготовить запуск новинки','Карточка, контент, поставка','Анна','ym')}${task('Собрать API-паспорт','Нет связки 6 SKU','Максим','goldapple')}</div><div class="kanban-col"><div class="kanban-head"><span>Контроль</span><span>7</span></div>${task('OOS Краснодар','Поставка подтверждена','Мария','magnit')}${task('Ответы на отзывы','12 обращений закрыто','Контент','letu')}</div></div></section>`}
