function iuDrr(){return `<div class="grid g3">${hero('Эффективность читается как поток денег','Вместо цветной матрицы — понятная цепочка от бюджета к трафику, заказам и ROMI.','8,6%','ДРР факт','248%')}${panel('Главный сигнал',`<div class="micro">отклонение к плану</div><div class="value lg" style="margin:13px 0;color:var(--warning)">+0,6 п.п.</div><div class="muted" style="font-size:9px;line-height:1.55">Перерасход формируют 3 кампании WB. Корректировка возвращает план без потери оборота.</div><div class="delta">−0,9 млн ₽ потенциал</div>`,'panel-pad platform-focus','решение')}</div>${panel('Деньги → трафик → результат',`<div class="flow"><div class="flow-node" style="--pc:var(--wb)"><strong>12,3 млн ₽</strong><span>расходы</span><i></i></div><div class="flow-node" style="--pc:var(--ozon)"><strong>21,9 млн</strong><span>показы</span><i></i></div><div class="flow-node" style="--pc:var(--ym)"><strong>380 тыс.</strong><span>клики</span><i></i></div><div class="flow-node" style="--pc:var(--goldapple)"><strong>142,4 млн ₽</strong><span>оборот</span><i></i></div></div>`,'panel-pad section-gap platform-line','единый поток')}<div class="grid g5 section-gap">${platformMetric('wb','WB','7,9%','ДРР · ROMI 264%','74%')}${platformMetric('ozon','Ozon','9,8%','ДРР · ROMI 218%','62%')}${platformMetric('ym','Я.Маркет','6,4%','ДРР · ROMI 291%','82%')}${platformMetric('goldapple','ЗЯ','4,8%','ДРР · ROMI 336%','91%')}${platformMetric('letu','Л’Этуаль','11,2%','ДРР · ROMI 184%','52%')}</div>`}
function rating(){return `<div class="grid g3">${hero('Репутация товара становится рабочей очередью','Оценка, отзывы, вопросы и качество контента собраны вокруг следующего действия.','4,76','средний рейтинг','4.8')}${panel('Очередь ответа',list([['gel_antiakne_20ml_v2','17 отзывов · 9 вопросов','26'],['retinol_syvorotka_1_30ml','7 отзывов · 5 вопросов','12'],['curly_method_300ml','34 отзыва · 3 вопроса','37'],['sprei_buster_100ml','12 отзывов · 1 вопрос','13']]),'panel-pad platform-focus','88 обращений')}</div><div class="grid g4 section-gap">${metric('Карточки','161','в контуре','100%')}${metric('Нужен ответ','38','−12 за неделю','41%')}${metric('Негатив 7д','5,6%','−1,1 п.п.','32%')}${metric('Вопросы','106','17 за 7 дней','64%')}</div><div class="grid g2 section-gap">${panel('Динамика рейтинга',lineChart([68,69,71,70,73,74,75,77,79,80,82,84],[64,66,68,69,70,72,73,75,76,77,79,81]),'panel-pad platform-line','30 дней')}${panel('Контент под контролем',list([['Главное фото','158 / 161','98%'],['Инфографика','149 / 161','93%'],['SEO-структура','141 / 161','88%'],['Ответы бренда','123 / 161','76%']]),'panel-pad','качество')}</div>`}
function leaderboard(){return `<div class="grid g3">${panel('Продукты, которые двигают результат',`<div class="podium"><div class="podium-item second"><div><div class="rank">2</div><strong>Сыворотка RET</strong><div class="value">+986</div><span>заказов · ROMI 312%</span></div></div><div class="podium-item first"><div><div class="rank">1</div><strong>Сыворотка SPF</strong><div class="value">+1 222</div><span>заказа · ROMI 288%</span></div></div><div class="podium-item third"><div><div class="rank">3</div><strong>Пенка CURLY</strong><div class="value">+831</div><span>заказ · ROMI 267%</span></div></div></div>`,'panel-pad span2 platform-line','КЗ · оборот · ROMI')}${panel('Метрики КЗ',list([['Выручка','28 839 заказов','18,6 млн ₽'],['ROMI','портфель','288,5%'],['ДРР','маркетинг','25,7%'],['Like for like','к прошлому периоду','+4 952']]),'panel-pad platform-focus','30 дней')}</div><div class="grid g4 section-gap">${metric('Охваты','51,4 млн','всех воронок','81%')}${metric('Клики','397 370','CTR 0,8%','64%')}${metric('Корзины','136 115','34,3% кликов','71%')}${metric('Выкупы','21 322','buyout 93,4%','93%')}</div><div class="grid g2 section-gap">${panel('Рост × эффективность',`<div class="bubbles"><span class="bubble" style="--x:18%;--y:62%;--s:62px;--pc:var(--wb)">SPF</span><span class="bubble" style="--x:42%;--y:38%;--s:88px;--pc:var(--ozon)">RET</span><span class="bubble" style="--x:67%;--y:57%;--s:74px;--pc:var(--ym)">CURLY</span><span class="bubble" style="--x:82%;--y:27%;--s:104px;--pc:var(--goldapple)">ANTI</span></div>`,'panel-pad platform-line','размер = выручка')}${panel('Ответственные',list([['Коммерция','7 209 SKU · 66 сигналов','1 место'],['Продукт','6 617 SKU · 40 сигналов','2 место'],['Маркетинг','5 845 SKU · 31 сигнал','3 место'],['Контент','4 952 LFL · 12 сигналов','4 место']]),'panel-pad','вклад команды')}</div>`}
const VIEWS={dashboard,executive,control,'data-health':calendarView,'sku-plan-fact':planFact,repricer,prices,order:orderView,'oos-control':oos,'sku-contour':skuWorkspace,launches,'launch-control':launchControl,'iu-drr':iuDrr,'wb-rating':rating,'product-leaderboard':leaderboard};
function buildNav(){const groups=[...new Set(ROUTES.map(r=>r.group))];$('.nav').innerHTML=groups.map(g=>`<div class="nav-group"><div class="nav-group-label">${g}</div>${ROUTES.filter(r=>r.group===g).map(r=>`<button class="nav-btn" data-route="${r.id}"><span class="nav-icon">${icon(r.icon)}</span><span><span class="nav-title">${r.title}</span><span class="nav-caption">${r.caption}</span></span><i class="nav-dot"></i></button>`).join('')}</div>`).join('');$$('.nav-btn').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.route)))}
function buildThemes(){const swatches=Object.entries(THEMES).map(([id,t])=>`<button class="theme-button" data-theme-id="${id}" title="${t.label}"><i style="background:${t.bgGradient.replace(/'/g,'&apos;')}"></i></button>`).join('');$('.theme-control').innerHTML=swatches;$('.theme-mini-row').innerHTML=Object.entries(THEMES).map(([id,t])=>`<button class="theme-swatch" data-theme-id="${id}" title="${t.label}" style="background:${t.accent}"></button>`).join('');$$('[data-theme-id]').forEach(b=>b.addEventListener('click',e=>setTheme(b.dataset.themeId,true,e)))}
function buildPlatforms(){const ids=['all','wb','ozon','ym','goldapple','letu','magnit'];$('.platforms').innerHTML=ids.map(id=>`<button class="platform-chip" data-platform-id="${id}" style="--pc:${PLATFORMS[id].color}"><i></i><span>${PLATFORMS[id].label}</span></button>`).join('');$$('[data-platform-id]').forEach(b=>b.addEventListener('click',()=>setPlatform(b.dataset.platformId,true)))}
function updateLogo(){const t=THEMES[activeTheme];$$('[data-brand-logo]').forEach(img=>img.src=LOGOS[t.logo]||LOGOS.white)}
function setTheme(id,animate=false,event=null){if(!THEMES[id])id='dark';const apply=()=>{activeTheme=id;$('.portal').dataset.theme=id;document.documentElement.dataset.theme=id;updateLogo();$$('[data-theme-id]').forEach(b=>b.classList.toggle('active',b.dataset.themeId===id));try{localStorage.setItem('altea.portal.theme',id)}catch(e){};ambientState.t=0};if(!animate){apply();return}const veil=$('.theme-veil');if(event){const r=$('.portal').getBoundingClientRect();veil.style.setProperty('--vx',`${event.clientX-r.left}px`);veil.style.setProperty('--vy',`${event.clientY-r.top}px`)}veil.classList.remove('flash');void veil.offsetWidth;veil.classList.add('flash');setTimeout(apply,180)}
function setPlatform(id,rerender=false){if(!PLATFORMS[id])id='all';activePlatform=id;$('.portal').dataset.platform=id;document.documentElement.dataset.platform=id;$$('[data-platform-id]').forEach(b=>b.classList.toggle('active',b.dataset.platformId===id));if(rerender)render(routeMap[activeRoute]);}
function setRouteVars(route){activeRoute=route.id;document.documentElement.style.setProperty('--route-accent',route.accent);document.documentElement.style.setProperty('--route-rgb',route.rgb);$('.portal').dataset.route=route.id;$('.crumb-index').textContent=route.index;$('.crumb strong').textContent=route.title;$$('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.route===route.id));$('.loader h2').textContent=route.title;$('.loader p').textContent=route.kicker;$('.loader-core').innerHTML=icon(route.icon)}
function head(route){return `<header class="route-head"><div><div class="route-kicker">${route.kicker}</div><h1>${route.headline}</h1><p>${route.title} · ${route.caption}. Сначала ответ, затем доказательство, после — детали по действию.</p></div><div class="route-actions"><button class="btn">Показать детали</button><button class="btn primary">Главное действие</button></div></header>`}
function render(route){setRouteVars(route);$('.route-stage').innerHTML=`<div class="route-enter">${head(route)}${VIEWS[route.id]()}</div>`;$('.content').scrollTop=0;}
function safeReplaceHash(id){try{history.replaceState(null,'',`#${id}`)}catch(e){try{location.hash=id}catch(_){}}}
function navigate(id,instant=false){const route=routeMap[id]||routeMap.dashboard;if(instant||$('.portal').dataset.capture==='1'){render(route);safeReplaceHash(route.id);return}if(busy)return;busy=true;setRouteVars(route);$('.loader').classList.add('show');setTimeout(()=>render(route),300);setTimeout(()=>{$('.loader').classList.remove('show');busy=false;safeReplaceHash(route.id)},820)}
function platformGuide(){const entries=Object.entries(PLATFORMS).filter(([id])=>id!=='all');$('.route-stage').innerHTML=`<div class="platform-guide"><div class="route-kicker">Marketplace micro-accents</div><h1>Цвет площадки — подпись, а не фон</h1><p>Каждая площадка получает узнаваемую точку цвета: 2 px линия, dot, chip или серия графика. Покрытие цвета — не более 8% экрана.</p><div class="platform-grid">${entries.map(([id,p])=>`<article class="platform-card" style="--pc:${p.color}"><h2>${p.long}</h2><div class="swatch-big"></div><code>${p.color} · ${p.rgb}</code><div class="usage-list"><span class="usage"><i></i>легенда и dot</span><span class="usage"><i></i>2 px линия карточки</span><span class="usage"><i></i>серия графика</span><span class="usage"><i></i>активный фильтр</span></div></article>`).join('')}</div></div>`}
let ambientState={ctx:null,c:null,w:0,h:0,dpr:1,frame:0,t:0};function hexRgb(hex){hex=hex.replace('#','');if(hex.length===3)hex=hex.split('').map(x=>x+x).join('');return [parseInt(hex.slice(0,2),16),parseInt(hex.slice(2,4),16),parseInt(hex.slice(4,6),16)]}
function drawAmbient(reset=false){const s=ambientState;if(!s.c)return;if(reset)s.t=0;const ctx=s.ctx,w=s.w,h=s.h;s.t+=.0028;ctx.clearRect(0,0,w,h);const tr=hexRgb(THEMES[activeTheme].accent),rr=hexRgb(routeMap[activeRoute]?.accent||THEMES[activeTheme].accent),pr=hexRgb(PLATFORMS[activePlatform].color);[[tr,.045,.72,.15,390],[rr,.052,.86,.48,330],[pr,.032,.60,.78,270]].forEach((q,i)=>{const [rgb,a,x0,y0,r]=q;const x=w*(x0+Math.sin(s.t*(1+i*.13)+i)*.05),y=h*(y0+Math.cos(s.t*.8+i)*.05);const g=ctx.createRadialGradient(x,y,0,x,y,r);g.addColorStop(0,`rgba(${rgb.join(',')},${a})`);g.addColorStop(1,`rgba(${rgb.join(',')},0)`);ctx.fillStyle=g;ctx.fillRect(x-r,y-r,r*2,r*2)});s.frame=requestAnimationFrame(()=>drawAmbient())}
function initAmbient(){const c=$('.ambient'),ctx=c.getContext('2d');ambientState.c=c;ambientState.ctx=ctx;function resize(){const dpr=Math.min(devicePixelRatio||1,2);ambientState.dpr=dpr;ambientState.w=c.clientWidth;ambientState.h=c.clientHeight;c.width=ambientState.w*dpr;c.height=ambientState.h*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}resize();addEventListener('resize',resize);drawAmbient()}
function params(){const q=new URLSearchParams(location.search);let saved='dark';try{saved=localStorage.getItem('altea.portal.theme')||'dark'}catch(e){}return {theme:q.get('theme')||saved,route:q.get('route')||location.hash.replace('#','')||'dashboard',platform:q.get('platform')||'all',capture:q.get('capture')||'',mode:q.get('mode')||''}}
function init(){buildNav();buildThemes();buildPlatforms();const p=params();$('.portal').dataset.capture=p.capture;setTheme(p.theme,false);setPlatform(p.platform,false);initAmbient();if(p.mode==='platforms'){platformGuide()}else{navigate(p.route,true)};addEventListener('hashchange',()=>{const id=location.hash.replace('#','');if(routeMap[id]&&id!==activeRoute)navigate(id)});window.AlteaThemeKit={navigate,setTheme,setPlatform,renderPlatformGuide:platformGuide,getState:()=>({activeRoute,activeTheme,activePlatform})};}
document.addEventListener('DOMContentLoaded',init);
